export const TRIBULATION_DESC_MAP: Record<string, string> = {
  '雷劫爆发极高,雷光之下护体灵光形同虚设。所幸雷息之间尚容调息,能疗伤者可撑。': 'Lôi kiếp bùng nổ cực cao, dưới ánh sét linh quang hộ thể thùng rỗng kêu to. May mà giữa các đợt sét còn có thể điều tức, người giỏi hồi phục có thể chống đỡ.',
  '劫中灵气逆乱,治疗恢复效果大减。久战者需另寻生路。': 'Linh khí trong kiếp hỗn loạn nghịch chuyển, hiệu quả trị liệu hồi phục giảm mạnh. Người đánh lâu cần tìm đường sống khác.',
  '劫雷直撼神魂,唯守中带稳者能从容。攻势足者可硬生生削去几分劫威。': 'Kiếp lôi chấn động thần hồn, chỉ người giữ vững căn cơ mới ung dung. Người có công thế mạnh mẽ có thể gọt bớt uy lực thiên kiếp.',
  '劫雷沉重绵密,层层碾落。护体灵光在这等钝压下几乎撑不住,唯绵长疗伤者可熬。': 'Kiếp lôi nặng nề dồn dập, tầng tầng nghiền nát. Linh quang hộ thể dưới áp lực nặng nề này khó bề chống đỡ, chỉ người có trị liệu bền bỉ mới vượt qua.',
  '起手两击雷霆万钧,其后转缓。若首轮护持不及,一切休提。': 'Khởi đầu hai kích lôi đình vạn quân, sau đó chậm lại. Nếu đợt đầu hộ trì không kịp thì khó thoát kiếp nạn.'
}

