  "纳神界至高之火,烈焰炽盛如九阳齐坠,焚毁诸神障": "Dung nạp ngọn lửa chí cao thần giới, hỏa diễm rực sáng tựa chín vầng thái dương rụng xuống",
  "神火裂虚,诸神退避": "Thần hỏa xé cõi, chư thần thoái lui",
  "真火淬道,神躯无伤": "Chân hỏa rèn đạo, thần thể không thương tích",
  "诸天帝王以神岳镇国,厚重莫测,压胜万灵": "Chư thiên đế vương dùng thần nhạc trấn quốc, dày nặng khôn lường, trấn áp vạn linh",
  "山岳崩灭,力贯千钧": "Non cao vỡ vụn, lực dội ngàn cân",
  "巍然不动,威严长存": "Sừng sững không dời, uy nghiêm trường tồn",
  "神诏如律令,号令诸天万界极道雷霆,行苍天杀伐": "Chiếu chỉ thần như sắc lệnh, chỉ huy lôi đình cực đạo của muôn cõi trời đất",
  "天诏破极,雷落无生": "Chiếu trời phá cực, lôi giáng tuyệt mạng",
  "神威如海,号令群雷": "Thần uy như biển, chỉ huy vạn lôi",
  "法冕加身,乘万劫无极神风,俯察神界兴废": "Đội miện pháp trên đầu, cưỡi thần phong muôn kiếp, nhìn xuống sự thịnh suy chư cõi",
  "狂风裂宙,所向无碍": "Gió giận xé trời, tiến bước không ngăn",
  "飘渺无痕,万法皆空": "Phiêu miểu không vết, vạn pháp thành không",
  "神帝至尊寒法,一念封冻诸天世界之运势": "Hàn pháp chí tôn của Thần Đế, một niệm đóng băng vận mệnh chư thiên thế giới",
  "冰封三千,生机俱灭": "Đóng băng ba ngàn cõi, sinh cơ đều diệt",
  "冰魄为尊,万劫不移": "Băng phách làm tôn, muôn kiếp không dời",
  "汲取鸿蒙本源之气,证真灵不灭真身,超拔天地之表": "Hấp thụ khí bản nguyên Hồng Mông, chứng ngộ chân linh bất diệt chân thân, vượt khỏi đất trời",
  "返本归源,神力盖世": "Về nguồn về gốc, thần lực áp đời",
  "身如鸿蒙,难毁难消": "Thân như Hồng Mông, khó hủy khó tan",
  "演混沌古神魔开天伟力,一斧劈开虚空乾坤": "Diễn hóa vĩ lực khai thiên của Thần Ma cổ xưa thời Hỗn Độn, một búa bổ toác càn khôn hư không",
  "霸力辟地,破尽诸天": "Bá lực xẻ đất, phá tan chư thiên",
  "开天立地,道骨长存": "Khai thiên lập địa, đạo cốt trường tồn",
  "达大道之源头,万法皆空,物我两忘,超脱一切法则": "Đạt tới ngọn nguồn đại đạo, vạn pháp thành không, quên mình quên vật, siêu thoát mọi quy luật",
  "源始之理,无往不利": "Lý lẽ cội nguồn, đánh đâu thắng đó",
  "身合无极,与道同休": "Thân hợp vô cực, cùng đạo trường tồn",
  "诸天万道归于混沌一元,一念可生世界,一念可灭寰宇": "Muôn vàn đạo trời quy về một mối Hỗn Độn, một niệm sinh thế giới, một niệm diệt hoàn vũ",
  "万道归真,威临绝顶": "Vạn đạo về chân, uy lâm tột đỉnh",
  "一气化生,万物难伤": "Một khí sinh hóa, vạn vật khó làm tổn thương",
  "调和体内阴阳二气,绵绵滋养脏腑": "Điều hòa âm dương nhị khí trong cơ thể, miên man nuôi dưỡng tạng phủ",
  "阴气内藏,气血悠长": "Âm khí nội tàng, khí huyết lâu dài",
  "阳气运转,筋骨坚稳": "Dương khí vận chuyển, gân cốt vững chãi",
  "以内息打熬骨骼,坚实如铁似玉": "Dùng nội tức tôi luyện xương cốt, cứng chắc như sắt tựa ngọc",
  "周身骨硬,御力沉凝": "Xương cốt cứng rắn, lực thủ trầm ngưng",
  "骨生微玉,体魄自壮": "Xương sinh ngọc mịn, thể phách tự cường",
  "步走离位,足下火生,游走若烈焰闪动": "Bước theo quẻ Ly, dưới chân sinh lửa, di chuyển tựa ánh lửa chập chờn",
  "火影闪现,避害从容": "Hỏa ảnh chớp giật, tránh hiểm thong dong",
  "热浪逼人,攻守自若": "Khí nóng bức người, công thủ tự nhiên",
  "聆听泉流清韵以养灵识,心无旁骛": "Lắng nghe suối reo thanh vận tĩnh dưỡng linh thức, tâm không tạp niệm",
  "明澈澄静,元气顺畅": "Trong sáng thanh tịnh, nguyên khí thông suốt",
  "见微知著,处世明察": "Thấy nhỏ biết lớn, hiểu thấu vạn vật",
  "引地脉厚土之温气培固丹田,厚重端正": "Dẫn khí ấm Hậu Thổ địa mạch củng cố đan điền, đôn hậu đoan chính",
  "根基稳如巨木,耐受风雨": "Căn cơ vững như cây lớn, chịu đựng mưa gió",
  "气机滋养灵材,获益颇丰": "Khí cơ nuôi dưỡng linh tài, thu hoạch dồi dào",
  "脚踏星斗之位,身形快若追星逐日": "Chân đạp phương vị tinh tú, thân hình nhanh tựa đuổi sao bắt trăng",
  "足踏天罡,避其锐气": "Chân đạp thiên cương, tránh mũi nhọn địch",
  "身游四方,搜罗灵奇": "Thân du bốn phương, tìm kiếm kỳ trân",
  "取劲竹经霜不折之意,修御敌守心之法": "Lấy ý tứ trúc xanh dầm sương không gãy, tu tập pháp môn thủ tâm phòng ngự",
  "劲节如铁,强力难伤": "Đốt tre như sắt, lực mạnh khó hại",
  "柔劲卸力,守御从容": "Nhu kình hóa giải, phòng thủ thong dong",
  "凝雨露之水汽以灌体培元,滋养身心": "Ngưng tụ hơi nước mưa móc rót vào cơ thể, tẩm bổ thân tâm",
  "雨润百草,采撷充盈": "Mưa nhuận trăm cỏ, hái lượm dồi dào",
  "流水润气,回元有度": "Nước chảy nhuận khí, hồi nguyên đều đặn",
  "引地心火意熔炼精金顽矿,增强臂力杀伐": "Dẫn hỏa ý lòng đất nung chảy tinh kim quặng sắt, tăng cường cánh tay sát phạt",
  "烈火化煞,剑气凌厉": "Lửa mạnh tan sát, kiếm khí lăng lệ",
  "神力开石,掘金得宝": "Thần lực mở đá, đào quặng tìm báu",
  "聚沉沙厚土以为壁垒,立如重山": "Gom tụ cát lắng đất dày làm hàng rào, đứng sừng sững như núi non",
  "重砂如墙,御敌御坚": "Cát nặng tựa tường, ngăn địch kiên cố",
  "血气如磐,不拔不移": "Huyết khí như bàn thạch, không lay không chuyển",
  "引九天罡风环绕周身,削弱敌势,身若飞絮": "Dẫn cửu thiên cương phong vây quanh thân thể, suy yếu thế địch, thân nhẹ tựa lông hồng",
