  "风罡回护,从容御伤": "Gió lốc xoay vòng, thong dong phòng hộ",
  "化极寒冰霜之息于体表,凝结一层无形霜甲": "Hóa cực hàn băng sương tức ngoài cơ thể, ngưng kết một tầng vô hình sương giáp",
  "冰霜固守,难伤分毫": "Băng sương cố thủ, khó tổn phân hào",
  "寒气逼退,杀伐自护": "Hàn khí bức lùi, sát phạt tự hộ",
  "引一缕紫霄天雷入体,激荡真气,出手狂猛": "Dẫn một sợi Tử Tiêu thiên lôi vào cơ thể, kích động chân khí, xuất chiêu cuồng mãnh",
  "雷光四溢,锋芒更甚": "Lôi quang tràn ngập, phong mang càng tăng",
  "雷音震心,破敌心胆": "Tiếng sấm kinh tâm, phá vỡ tâm can kẻ địch",
  "采集正午神光入体,诸邪退避,体质纯阳": "Thu thập thần quang chính ngọ vào thân, tà ma lui bước, thể chất thuần dương",
  "阳火护身,百毒难侵": "Dương hỏa hộ thân, bách độc khó xâm",
