  "隐匿身形气机于幽暗阴影之中,悄无声息": "Ẩn nấp thân hình khí tức trong bóng tối u uất, lặng lẽ không một tiếng động",
  "如影随形,难测去留": "Như hình với bóng, khó dò phương hướng",
  "阴极生吉,偶得奇遇": "Âm cực sinh cát, tình cờ gặp kỳ ngộ",
  "致虚极,守静笃,灵台空明,参道通达": "Tột cùng hư không, giữ tròn tĩnh lặng, linh đài rỗng sáng, ngộ đạo thông suốt",
  "澄神绝照,修持益稳": "Lắng thần chiếu sáng, tu trì vững vàng",
  "灵台通明,关卡易渡": "Linh đài thông tỏ, cửa ải dễ qua",
  "聚金煞锐气淬砺剑锋,开石断玉只在一指之间": "Gom kim sát sắc bén mài giũa mũi kiếm, xẻ đá cắt ngọc chỉ trong một ngón tay",
