  "纯火如罡,势不可当": "Thuần hỏa như cương, khí thế khó cản",
  "暴劲迸发,重创顽敌": "Kình lực bùng nổ, trọng thương cường địch",
  "依五行生克遁走山川万物,御气如飞": "Nương theo ngũ hành tương sinh tương khắc độn qua non sông vạn vật, ngự khí như bay",
  "随物化遁,莫可触及": "Tùy vật hóa độn, không thể chạm tới",
  "周天迅步,从容自若": "Bước chân mau lẹ, thong dong tự tại",
