  "心无挂碍,安如古井": "Tâm không vướng bận, yên ả tựa giếng cổ",
  "神光普照,修途明朗": "Thần quang chiếu khắp, nẻo tu sáng ngời",
  "以九幽阴煞凝聚护神法衣,危难之时愈显凶性": "Dùng cửu u âm sát ngưng tụ pháp y hộ thần, lúc hiểm nguy càng hiển lộ hung tính",
  "深煞护命,绝境逢生": "Sát khí hộ mạng, trong tuyệt cảnh tìm thấy sự sống",
  "九幽沉璧,难破半分": "Cửu u vách chắn, khó phá nửa phần",
