  "以柔克刚,反劲伤敌": "Lấy mềm chế cứng, dội ngược kình lực",
  "天河护体,水波荡漾": "Sông trời hộ thể, sóng nước dập dờn",
  "烈焰化为纯阳神钟倒扣周身,触之者被烈火反噬": "Lửa mạnh hóa thành chuông thần thuần dương chụp quanh người, kẻ chạm vào liền bị phản phệ",
  "神钟长鸣,御力卓绝": "Chuông thần vang rền, phòng ngự trác tuyệt",
  "烈火灼敌,伤我者死": "Lửa mạnh đốt địch, kẻ hại ta phải trả giá",
  "周身百穴凝结混元金刚之膜,刀枪难入水火不侵": "Trăm huyệt toàn thân ngưng màng kim cương hỗn nguyên, đao thương khó lọt nước lửa chẳng sờn",
  "肉身如铁,万刃难折": "Thân xác như sắt, vạn đao khôn cong",
  "五行相护,百灾不磨": "Ngũ hành bảo vệ, trăm kiếp chẳng sờn",
  "聚九幽阴煞凝作轻薄黑纱,来攻之兵刃皆被腐蚀": "Gom âm sát chín cõi u minh dệt lớp áo sa đen mỏng manh, binh khí chém tới đều bị ăn mòn rỉ sét",
  "阴煞蔽体,绝境逢安": "Âm sát che người, bước vào đường cùng vẫn bình an",
  "腐劲伤骨,折敌锋芒": "Ăn mòn gãy xương, bẻ gãy mũi nhọn của địch",
  "身化远古蛮荒天柱神岳,稳如泰山任凭风吹浪打": "Thân hóa núi trụ trời thời thượng cổ hoang dã, vững như Thái Sơn mặc cho gió quất sóng dập",
  "神岳当关,万力不侵": "Thần sơn trấn ải, muôn vạn sức mạnh không thể phạm",
  "气血雄沉,命元悠远": "Khí huyết hùng dũng, mệnh căn dài lâu",
  "头顶升起玄冥神气光罩,隔绝诸界五行术法伤害": "Đầu đội lồng khí thần Huyền Minh tỏa sáng, ngăn cách mọi đòn đánh pháp thuật ngũ hành các cõi",
  "五行难伤,从容破法": "Ngũ hành khó tổn thương, thong thả phá pháp",
  "神光如幕,守御固本": "Ánh thần như rèm, củng cố phòng ngự",
  "天雷聚为周身奔腾战甲,受创之时神雷狂轰袭击者": "Thiên lôi ngưng tụ thành giáp chiến rực lửa quanh người, khi chịu đòn thì sấm sét lập tức dội thẳng kẻ tấn công",
  "奔雷护体,坚固绝伦": "Sấm lôi bảo vệ, bền chắc tuyệt luân",
  "触者遭劫,雷殛顽凶": "Chạm vào gặp kiếp, sét đánh kẻ hung",
  "大罗仙光重塑仙体,任凭天劫地难临身亦不磨灭": "Ánh sáng tiên Đại La tái tạo thân tiên, mặc kệ kiếp trời nạn đất ập vào thân cũng không tiêu biến",
  "超脱劫数,永享清平": "Vượt ngoài kiếp số, hưởng cõi an nhàn",
  "大罗仙障,神兵难损": "Tấm khiên Đại La, thần binh khó gãy",
  "瑶池万年温玉所化宝铠,贴身护住三魂七魄": "Giáp báu kết từ ngọc ấm vạn năm Dao Trì, kề sát bảo vệ ba hồn bảy phách",
  "温玉化甲,从容御劫": "Ngọc ấm hóa giáp, thong dong đỡ kiếp",
  "神魄无瑕,安如泰岳": "Thần phách vẹn toàn, vững như núi cao",
  "以太虚无极罡气消弭万千劫数,万物触之皆化无形": "Dùng thái hư vô cực cương khí tiêu tan vạn nghìn tai kiếp, vật chạm vào đều hóa vô hình",
  "劫难消散,身如长风": "Tai kiếp tan biến, thân tựa gió dài",
  "虚空同体,无懈可乘": "Cùng thể hư không, chẳng hở sơ hở",
  "纳亿万星云环抱法体,如同身负诸天银河": "Gom hàng ức mây sao ôm trọn pháp thể, tựa như mang trên mình dải ngân hà chư thiên",
  "银河为甲,坚不可破": "Ngân hà làm giáp, kiên cố khôn phá",
  "星芒化盾,抵挡杀伐": "Ánh sao làm khiên, cản đòn sát phạt",
  "凝聚上古神帝之皇道帝气,成就永恒不磨之神铠": "Ngưng tụ hoàng đạo đế khí của Thần Đế thượng cổ, thành tựu giáp thần vĩnh hằng không hoại",
  "帝躯至圣,万神臣服": "Thân đế chí thánh, muôn thần cúi đầu",
  "不灭真金,硬若天界": "Vàng ròng bất diệt, cứng tựa cõi tiên",
  "以宇宙至高防御法则构建神壁,不可逾越": "Dùng quy luật phòng ngự tối cao của vũ trụ dựng nên bức tường thần, không thể vượt qua",
  "界壁立前,隔断天堑": "Vách ngăn dựng trước, chắn ngang rãnh trời",
  "法则加持,命基长固": "Quy luật gia trì, gốc mệnh trường tồn",
  "神王顶戴帝冕降下神符,濒死之时瞬间化险为夷": "Thần Vương đội mũ đế giáng xuống bùa thần, lúc lâm nguy tức khắc chuyển nguy thành an",
  "王冕护神,诸煞难侵": "Mũ vương hộ thần, mọi sát khó phạm",
  "真符延寿,化险为夷": "Bùa thật kéo dài thọ mệnh, chuyển nguy thành an",
  "以鸿蒙初开之太初之气凝就混沌古钟,万劫不动": "Dùng khí thái sơ lúc Hồng Mông hé mở kết thành chuông cổ Hỗn Độn, vạn kiếp khôn lay",
  "钟鸣定界,镇压因果": "Chuông vang định giới, trấn áp nhân quả",
  "万力归虚,万物难伤": "Vạn lực về không, vạn vật khó hại",
  "与无极大道相合,身即是天地,天地即是身": "Hòa mình cùng đại đạo Vô Cực, thân chính là đất trời, đất trời chính là thân",
  "神躯无铸,不死不休": "Thần thể đúc thành, bất tử bất diệt",
  "脚踏清风,凌波微步,身形飘忽若仙": "Chân đạp gió lành, lướt sóng nhẹ nhàng, thân hình phiêu dật tựa tiên nhân",
  "足不沾尘,避害自如": "Chân không dính bụi, tránh nạn tự nhiên",
  "乘风自适,行动从容": "Cưỡi gió thảnh thơi, cử chỉ ung dung",
  "身若灵燕破空穿云,行动迅捷莫测": "Thân tựa chim yến vút mây xé gió, hành động mau lẹ khôn lường",
  "穿云破雾,极速远行": "Xuyên mây rẽ sương, đi xa cực nhanh",
  "轻灵回旋,闪转自如": "Nhẹ nhàng xoay chuyển, lượn lách tự tại",
  "分化九重暗夜残影,真身难测,敌攻尽皆落空": "Phân hóa chín tầng tàn ảnh đêm tối, chân thân khó dò, đòn địch đều hụt vào hư không",
  "残影重重,诱敌落空": "Bóng ảo chập chờn, dỗ địch đánh hụt",
  "遁入夜幕,从容脱身": "Ẩn vào màn đêm, thong dong thoát hiểm",
  "身化电芒一闪而逝,跨越虚空只在瞬息": "Thân hóa tia sét vụt lóe rồi tắt, vượt qua hư không chỉ trong một hơi thở",
  "雷光骤至,先夺敌先": "Ánh lôi chợt tới, đoạt thế tiên phong",
  "雷行无阻,进退随心": "Sét đi không cản, tiến thoái tùy tâm",
  "参悟大地脉理,一步踏出咫尺化为千里天涯": "Hiểu thấu mạch ngầm đại địa, một bước đặt xuống gang tấc hóa ngàn dặm chân trời",
  "咫尺天涯,神游八表": "Gang tấc chân trời, dạo bước tám cõi",
  "步入地脉,敌难追踪": "Bước vào lòng đất, giặc khôn đuổi theo",
  "烈焰化为两道狂暴火翼,振翅之间掠过苍穹": "Lửa thiêng hóa hai cánh hỏa cuồng bạo, vỗ cánh một cái lướt qua bầu trời",
  "展翅冲霄,身动雷随": "Tung cánh ngút mây, thân dời sấm theo",
  "奔流如虹,神形难测": "Cuồn cuộn như vồng, thần hình khó đoán",
  "身躯彻底融汇于九霄罡风之中,无影无形": "Thân xác hoàn toàn tan vào chín tầng cương phong, không hình không bóng",
  "不见形迹,避无可避": "Chẳng thấy tung tích, khôn đường đánh trúng",
  "罡风绕行,随风自化": "Cương phong quanh thân, nương gió tự tan",
  "步过之处凝结晶莹冰霜,踏冰而行绝尘而去": "Bước chân lướt qua kết sương băng lấp lánh, đạp băng mà đi bụi trần khôn vướng",
  "踏霜无迹,身形飘忽": "Đạp sương không dấu, thân hình chập chờn",
  "冰霜阻敌,从容避祸": "Băng sương cản bước, ung dung lánh nạn",
  "踩周天星斗之方位行进,一步可跨一重天地": "Đạp theo phương vị tinh tú khắp trời mà tiến, một bước có thể băng qua một tầng trời đất",
  "移星换斗,瞬息无踪": "Dời sao đổi đẩu, chớp mắt không dấu",
