  "乘大罗仙霞云气逍遥而行,跨界逐月": "Cưỡi ráng mây Đại La tiêu dao mà đi, vượt cõi đuổi trăng",
  "漫步虚空,诸险难加": "Dạo bước hư không, mọi nạn khôn tới",
  "云霞蔽日,身遁无形": "Mây che bóng râm, thân ẩn vô hình",
  "身如瑶台仙子踏空飞升,超拔于万丈红尘之外": "Thân tựa tiên tử Dao Trì bay lượn hư không, thoát khỏi chốn hồng trần muôn trượng",
  "凌虚远遁,神鬼难测": "Lướt cõi đi xa, quỷ thần khó lường",
  "仙华流转,进退从容": "Tiên hoa xoay vần, tiến thoái thong dong",
  "太乙神雷破开虚空阻隔,神躯直入天外太虚": "Thần lôi Thái Ất xé toang vách ngăn hư không, thân thể tiến thẳng vào thái hư ngoài trời",
  "破空如电,敌势落空": "Xé gió như chớp, đòn địch hụt tăm",
  "清风雷引,行者从容": "Gió mát sấm đưa, hành xử thong dong",
  "神帝巡视大千世界,一步之下诸界山河皆在脚底": "Thần Đế tuần du đại thiên thế giới, một bước phóng ra muôn dặm non sông đều dưới bàn chân",
  "神行无疆,万界俯首": "Thần đi không bến, muôn cõi cúi mình",
  "威严无上,诸阻尽消": "Uy nghiêm tột bực, mọi cản trở tan biến",
  "执掌空间法则枢纽,天地之间再无距离之分": "Nắm giữ then chốt của quy luật không gian, đất trời giữa muôn nơi không còn khoảng cách",
  "心念所至,身形立达": "Ý nghĩ vừa tới, thân hình tức thì xuất hiện",
  "虚空折叠,探宝如取": "Gấp nếp hư không, lấy bảo bối như lấy đồ trong túi",
  "化身为无形混沌之气,游走于纪元崩灭之时": "Hóa thân làm luồng khí hỗn độn vô hình, dạo chơi qua các thời kỳ kỷ nguyên sụp đổ",
  "与道合真,不可捉摸": "Hòa cùng chân đạo, không thể bắt nắm",
  "游于无界,安享永劫": "Dạo cõi vô biên, hưởng trọn vạn kiếp",
  "跳出三界外不在五行中,身在无极亦在万方": "Nhảy ra khỏi ba cõi không nằm trong ngũ hành, thân ở Vô Cực cũng hiện khắp muôn phương",
  "超出因果,神游无限": "Vượt ngoài nhân quả, thần du vô hạn",
  "道祖临凡,万物避道": "Đạo tổ giáng trần, vạn vật nhường đường",
  "止熄妄念,内观气海,吐纳真气绵长平稳": "Dập tắt tạp niệm, nhìn sâu vào khí hải, thổ nạp chân khí êm đềm bình ổn",
  "心无杂质,修为精纯": "Lòng không vẩn đục, tu vi tinh thuần",
  "气脉通达,生生不息": "Khí mạch thông tỏ, sinh sôi không dứt",
  "通晓灵药草木枯荣之理,采集所得灵性倍增": "Tường tận quy luật héo tươi cỏ thuốc linh dược, hái lượm được linh tính tăng gấp bội",
  "识药得真,采药倍获": "Biết thuốc tìm thật, hái thuốc bội thu",
  "灵丹化生,药力绵绵": "Linh đan sinh nở, dược lực dồi dào",
  "以心火温养炉鼎矿脉,探寻顽石之中的至精玄铁": "Dùng tâm hỏa ủ ấm quặng mỏ lò đan, tìm kiếm huyền thiết tinh túy trong đá tảng",
  "矿石化纯,收获颇丰": "Quặng đá hóa ròng, gặt hái rất nhiều",
  "温火慢炖,丹成上乘": "Lửa êm ninh chậm, đan dược hảo hạng",
  "聚林木之万千生机反哺己身,延年益寿": "Gom muôn vàn sinh cơ của rừng cây bù đắp bản thân, kéo dài tuổi thọ dồi dào sức sống",
  "木气化津,生机长存": "Mộc khí hóa dịch, sinh cơ bền lâu",
  "五气朝元,神清气爽": "Năm khí chầu về, thần thanh khí sảng",
  "以造化生灵之火温养丹药,丹效通神": "Dùng lửa tạo hóa sinh linh nuôi nấng đan dược, dược hiệu thông thần",
  "神丹吞服,功效大增": "Uống đan thần diệu, hiệu quả tăng vọt",
  "药力洗髓,冲破关卡": "Dược lực tẩy tủy, phá tan cửa ải",
  "于太虚之中布设引灵玄阵,汇聚万里纯灵入体": "Tại thái hư bày bố huyền trận dẫn linh, gom tụ linh khí thuần khiết vạn dặm vào người",
  "灵潮如海,吐纳日进": "Triều linh như biển, thổ nạp tiến xa",
  "根基固若神峰,无惧阻滞": "Căn cơ vững như ngọn núi thần, chẳng ngại đình trệ",
  "勘测八荒地脉之走势,寻龙点穴采掘万年真金": "Khảo sát mạch ngầm tám phương trời, điểm huyệt tầm long đào bới vạn năm chân kim",
  "掘金得玉,矿藏倍丰": "Đào vàng được ngọc, quặng mỏ dồi dào",
  "地气通畅,草木化珍": "Địa khí hanh thông, cây cỏ hóa báu",
  "引九天玉液甘露洗髓伐脉,通体晶莹气血畅通": "Dẫn sương ngọt ngọc dịch chín tầng trời gột rửa tủy mạch, toàn thân trong suốt khí huyết thông suốt",
  "神露涤身,旧疾尽消": "Sương thần tẩy trần, bệnh cũ tan biến",
  "体内无秽,道法自然": "Trong người không nhơ, đạo pháp thuận tự nhiên",
  "顺应天道运转周天之息,修持速度一日千里": "Thuận theo thiên đạo vận hành chu thiên tức, tốc độ tu trì một ngày ngàn dặm",
  "生生运转,修为猛进": "Vận chuyển không dứt, tu vi tiến vọt",
  "道眼通达,破劫如履": "Mắt đạo thông suốt, vượt kiếp dễ dàng",
  "以瑶池仙水灌溉天下灵植,仙药成材速度倍增": "Dùng nước tiên Dao Trì tưới tắm linh thực thiên hạ, tốc độ thuốc tiên lớn mạnh tăng gấp bội",
