  "仙材成丹,药力通天": "Tiên tài thành đan, dược lực ngút trời",
  "载录玉虚九转金丹之玄妙法门,服之延寿万载": "Chép lại huyền môn kim đan chín chuyển Ngọc Hư, uống vào thọ muôn năm",
  "金丹九转,妙用通玄": "Kim đan chín chuyển, diệu dụng thông huyền",
  "药力破障,境界大成": "Dược lực phá rào, cảnh giới viên mãn",
  "引大罗天清净仙气入心宫,洗去万劫红尘羁绊": "Dẫn khí tiên thanh tịnh cõi Đại La vào tâm cung, gột sạch vướng bận hồng trần muôn kiếp",
  "灵台绝照,修为沛然": "Linh đài sáng tỏ, tu vi dạt dào",
